QString DecodeError::formatted() const { return path.isEmpty() ? message : path + ": " + message; }

namespace {
struct Reader {
    QString error;
    bool object(const QJsonValue &v, const QString &p, QJsonObject &out) { if (!v.isObject()) return fail(p,"expected object"); out=v.toObject(); return true; }
    bool array(const QJsonObject &o,const char *k,const QString&p,QJsonArray&v){auto x=o.value(k);if(x.isUndefined())return fail(p+"."+k,"missing required field");if(!x.isArray())return fail(p+"."+k,"expected array");v=x.toArray();return true;}
    bool str(const QJsonObject&o,const char*k,const QString&p,QString&v,bool nullable=false){auto x=o.value(k);QString q=p+"."+k;if(x.isUndefined())return fail(q,"missing required field");if(nullable&&x.isNull()){v.clear();return true;}if(!x.isString())return fail(q,QString("expected string")+(nullable?" or null":""));v=x.toString();return true;}
    bool boolean(const QJsonObject&o,const char*k,const QString&p){auto x=o.value(k);if(x.isUndefined())return fail(p+"."+k,"missing required field");return x.isBool()||fail(p+"."+k,"expected boolean");}
    bool number(const QJsonObject&o,const char*k,const QString&p,bool nullable=false){auto x=o.value(k);QString q=p+"."+k;if(x.isUndefined())return fail(q,"missing required field");return (x.isDouble()||(nullable&&x.isNull()))||fail(q,QString("expected number")+(nullable?" or null":""));}
    bool enumv(const QJsonObject&o,const char*k,const QString&p,const QStringList&a,QString&v,bool nullable=false){if(!str(o,k,p,v,nullable))return false;if(nullable&&o.value(k).isNull())return true;if(!a.contains(v))return fail(p+"."+k,"expected one of "+a.join('|'));return true;}
    bool nullableString(const QJsonObject&o,const char*k,const QString&p){QString x;return str(o,k,p,x,true);}
    bool fail(const QString&p,const QString&m){if(error.isEmpty())error=(p.isEmpty()?m:p+": "+m);return false;}
};
const QStringList blocks={"night","fajr","dhuhr","asr","maghrib","isha"}, boundaries={"night","fajr","dhuhr","asr","maghrib","isha","sleep"};
const QStringList prayers={"fajr","dhuhr","asr","maghrib","isha"}, repeats={"none","daily","weekly"}, measures={"check","minutes","count"}, states={"open","done","missed"}, weekdays={"mon","tue","wed","thu","fri","sat","sun"};

bool weekdaysField(Reader&r,const QJsonObject&o,const QString&p){auto v=o.value("weekdays");if(v.isUndefined())return r.fail(p+".weekdays","missing required field");if(v.isNull())return true;if(!v.isArray())return r.fail(p+".weekdays","expected array or null");for(int i=0;i<v.toArray().size();++i){auto x=v.toArray()[i];if(!x.isString()||!weekdays.contains(x.toString()))return r.fail(p+QString(".weekdays[%1]").arg(i),"expected one of "+weekdays.join('|'));}return true;}
bool dayItem(Reader&r,const QJsonValue&v,const QString&p,DayItem&x){QJsonObject o;if(!r.object(v,p,o))return false;x.json=o;if(!r.str(o,"id",p,x.id)||!r.str(o,"title",p,x.title)||!r.enumv(o,"block",p,blocks,x.block)||!r.enumv(o,"repeat",p,repeats,x.repeat)||!weekdaysField(r,o,p)||!r.enumv(o,"measure",p,measures,x.measure)||!r.number(o,"target",p,true)||!r.number(o,"position",p)||!r.enumv(o,"state",p,states,x.state)||!r.number(o,"minutes",p)||!r.number(o,"count",p)||!r.nullableString(o,"timer_started_at",p))return false;return true;}
bool item(Reader&r,const QJsonValue&v,const QString&p,Item&x){QJsonObject o;if(!r.object(v,p,o))return false;x.json=o;if(!r.str(o,"id",p,x.id)||!r.str(o,"title",p,x.title)||!r.enumv(o,"block",p,blocks,x.block)||!r.enumv(o,"repeat",p,repeats,x.repeat)||!weekdaysField(r,o,p)||!r.enumv(o,"measure",p,measures,x.measure)||!r.number(o,"target",p,true)||!r.number(o,"position",p)||!r.str(o,"day",p,x.title)||!r.str(o,"created_at",p,x.title)||!r.str(o,"updated_at",p,x.title)||!r.nullableString(o,"deleted_at",p))return false;return true;}
bool entry(Reader&r,const QJsonValue&v,const QString&p,Entry&x){QJsonObject o,b;if(!r.object(v,p,o))return false;x.json=o;if(!r.str(o,"id",p,x.id)||!r.str(o,"item_id",p,x.itemId)||!r.enumv(o,"kind",p,{"done","minutes","count","timer"},x.kind)||!r.object(o.value("block"),p+".block",b))return false;QString z;if(!r.str(b,"day",p+".block",z)||!r.enumv(b,"start",p+".block",blocks,z)||!r.number(o,"value",p,true)||!r.nullableString(o,"started_at",p)||!r.nullableString(o,"ended_at",p)||!r.str(o,"created_at",p,z)||!r.str(o,"updated_at",p,z)||!r.nullableString(o,"deleted_at",p))return false;return true;}
bool prayerMark(Reader&r,const QJsonValue&v,const QString&p,PrayerMark&x){QJsonObject o;if(!r.object(v,p,o))return false;x.json=o;if(!r.str(o,"id",p,x.id)||!r.str(o,"day",p,x.day)||!r.enumv(o,"prayer",p,prayers,x.prayer)||!r.str(o,"marked_at",p,x.day)||!r.str(o,"created_at",p,x.day)||!r.str(o,"updated_at",p,x.day)||!r.nullableString(o,"deleted_at",p))return false;return true;}
bool mutationResult(Reader&r,const QJsonValue&v,MutationResult&x){
    QJsonObject o,changed;
    if(!r.object(v,"mutation",o))return false;
    x.json=o;
    if(!r.number(o,"revision","mutation")||!r.str(o,"op_id","mutation",x.opId))return false;
    x.revision=o.value("revision").toVariant().toLongLong();
    if(!r.object(o.value("changed"),"mutation.changed",changed))return false;
    QJsonArray items,entries,marks,deleted;
    if(!r.array(changed,"items","mutation.changed",items)||!r.array(changed,"entries","mutation.changed",entries)||!r.array(changed,"marks","mutation.changed",marks)||!r.array(changed,"deleted","mutation.changed",deleted))return false;
    for(int i=0;i<items.size();++i){DayItem d;if(!dayItem(r,items[i],QString("mutation.changed.items[%1]").arg(i),d))return false;x.items.push_back(std::move(d));}
    for(int i=0;i<entries.size();++i){Entry e;if(!entry(r,entries[i],QString("mutation.changed.entries[%1]").arg(i),e))return false;x.entries.push_back(std::move(e));}
    for(int i=0;i<marks.size();++i){PrayerMark m;if(!prayerMark(r,marks[i],QString("mutation.changed.marks[%1]").arg(i),m))return false;x.marks.push_back(std::move(m));}
    for(int i=0;i<deleted.size();++i){if(!deleted[i].isString())return r.fail(QString("mutation.changed.deleted[%1]").arg(i),"expected string");x.deleted.push_back(deleted[i].toString());}
    return true;
}
template<class T,class F> Decoded<T> run(const QJsonValue&v,F f){Reader r;T x;if(f(r,v,x))return {std::move(x),{}};const int n=r.error.indexOf(": ");return Decoded<T>{{},DecodeError{n<0?QString():r.error.left(n),n<0?r.error:r.error.mid(n+2)}};}
template<class T> AnyDecoded any(Decoded<T> d){if(!d)return {{},d.error};return {Value{std::move(*d.value)},{}};}
}

template<> Decoded<DayPlan> decode<DayPlan>(const QJsonValue&v){return run<DayPlan>(v,[](Reader&r,const QJsonValue&v,DayPlan&x){QJsonObject o;if(!r.object(v,"day",o))return false;x.json=o;if(!r.str(o,"day","day",x.day)||!r.boolean(o,"is_today","day")||!r.str(o,"sunrise","day",x.day)||!r.str(o,"night_start","day",x.day)||!r.number(o,"open","day"))return false;QJsonObject sl;if(!r.object(o.value("sleep"),"day.sleep",sl)||!r.str(sl,"time","day.sleep",x.sleep.time)||!r.boolean(sl,"passed","day.sleep"))return false;x.sleep.json=sl;if(!o.contains("now"))return r.fail("day.now","missing required field");if(!o.value("now").isNull()){QJsonObject n,next;if(!r.object(o.value("now"),"day.now",n)||!r.enumv(n,"block","day.now",blocks,x.sleep.time)||!r.boolean(n,"sleeping","day.now")||!r.object(n.value("next"),"day.now.next",next))return false;QString z;if(!r.enumv(next,"id","day.now.next",boundaries,z)||!r.str(next,"name","day.now.next",z)||!r.str(next,"time","day.now.next",z)||!r.number(next,"remaining_seconds","day.now.next"))return false;x.now=Now{n,n.value("block").toString()};}QJsonArray a;if(!r.array(o,"prayers","day",a))return false;for(int i=0;i<a.size();++i){QJsonObject p;QString z;if(!r.object(a[i],QString("day.prayers[%1]").arg(i),p)||!r.enumv(p,"id",QString("day.prayers[%1]").arg(i),prayers,z)||!r.str(p,"name",QString("day.prayers[%1]").arg(i),z)||!r.str(p,"time",QString("day.prayers[%1]").arg(i),z)||!r.boolean(p,"passed",QString("day.prayers[%1]").arg(i))||!r.boolean(p,"current",QString("day.prayers[%1]").arg(i))||!r.boolean(p,"marked",QString("day.prayers[%1]").arg(i)))return false;x.prayers.push_back({p,p.value("id").toString()});}if(!r.array(o,"blocks","day",a))return false;for(int i=0;i<a.size();++i){QString bp=QString("day.blocks[%1]").arg(i);QJsonObject b;DayBlock db;if(!r.object(a[i],bp,b)||!r.enumv(b,"start",bp,blocks,db.start)||!r.enumv(b,"end",bp,boundaries,db.end))return false;db.json=b;QJsonArray its;if(!r.array(b,"items",bp,its))return false;for(int j=0;j<its.size();++j){DayItem di;if(!dayItem(r,its[j],bp+QString(".items[%1]").arg(j),di))return false;db.items.push_back(std::move(di));}x.blocks.push_back(std::move(db));}return true;});}
template<> Decoded<Stats> decode<Stats>(const QJsonValue&v){return run<Stats>(v,[](Reader&r,const QJsonValue&v,Stats&x){QJsonObject o;if(!r.object(v,"stats",o))return false;x.json=o;if(!r.str(o,"from","stats",x.from)||!r.str(o,"to","stats",x.to)||!r.number(o,"days","stats")||!r.number(o,"marked_total","stats")||!r.number(o,"prayer_slots","stats"))return false;QJsonArray a;if(!r.array(o,"items","stats",a))return false;for(int i=0;i<a.size();++i){QString p=QString("stats.items[%1]").arg(i);QJsonObject q;StatsItem si;if(!r.object(a[i],p,q))return false;si.json=q;if(!r.str(q,"id",p,si.id)||!r.str(q,"title",p,si.title)||!r.enumv(q,"block",p,blocks,si.block)||!r.enumv(q,"repeat",p,repeats,si.repeat)||!weekdaysField(r,q,p)||!r.enumv(q,"measure",p,measures,si.measure)||!r.number(q,"target",p,true)||!r.number(q,"planned_days",p)||!r.number(q,"done_days",p)||!r.number(q,"minutes",p)||!r.number(q,"count",p))return false;QJsonArray s;if(!r.array(q,"series",p,s))return false;for(int j=0;j<s.size();++j){QString sp=p+QString(".series[%1]").arg(j);QJsonObject z;QString day;if(!r.object(s[j],sp,z)||!r.str(z,"day",sp,day)||!r.boolean(z,"planned",sp)||!r.boolean(z,"done",sp)||!r.number(z,"minutes",sp)||!r.number(z,"count",sp))return false;si.series.push_back({z,day});}x.items.push_back(std::move(si));}if(!r.array(o,"prayers","stats",a))return false;for(int i=0;i<a.size();++i){QString p=QString("stats.prayers[%1]").arg(i),z;QJsonObject q;if(!r.object(a[i],p,q)||!r.enumv(q,"prayer",p,prayers,z)||!r.number(q,"marked_days",p)||!r.number(q,"days",p))return false;x.prayers.push_back({q,z});}if(!r.array(o,"daily","stats",a))return false;for(int i=0;i<a.size();++i){QString p=QString("stats.daily[%1]").arg(i),z;QJsonObject q;if(!r.object(a[i],p,q)||!r.str(q,"day",p,z)||!r.number(q,"planned",p)||!r.number(q,"done",p)||!r.number(q,"minutes",p)||!r.number(q,"count",p)||!r.number(q,"prayers",p))return false;x.daily.push_back({q,z});}QJsonObject t;if(!r.object(o.value("totals"),"stats.totals",t))return false;for(auto k:{"planned","done","minutes","count","prayers","active_days"})if(!r.number(t,k,"stats.totals"))return false;x.totals={t};return true;});}
template<> Decoded<Item> decode<Item>(const QJsonValue&v){return run<Item>(v,[](Reader&r,const QJsonValue&v,Item&x){return item(r,v,"item",x);});}
template<> Decoded<Entry> decode<Entry>(const QJsonValue&v){return run<Entry>(v,[](Reader&r,const QJsonValue&v,Entry&x){return entry(r,v,"entry",x);});}
template<> Decoded<std::vector<Entry>> decode<std::vector<Entry>>(const QJsonValue&v){return run<std::vector<Entry>>(v,[](Reader&r,const QJsonValue&v,std::vector<Entry>&x){if(!v.isArray())return r.fail("entries","expected array");for(int i=0;i<v.toArray().size();++i){Entry e;if(!entry(r,v.toArray()[i],QString("entries[%1]").arg(i),e))return false;x.push_back(std::move(e));}return true;});}
template<> Decoded<ParseDraft> decode<ParseDraft>(const QJsonValue&v){return run<ParseDraft>(v,[](Reader&r,const QJsonValue&v,ParseDraft&x){QJsonObject o;if(!r.object(v,"draft",o))return false;x.json=o;QString block;if(!r.str(o,"title","draft",x.title)||!r.enumv(o,"block","draft",blocks,block,true)||!r.enumv(o,"repeat","draft",repeats,x.repeat)||!weekdaysField(r,o,"draft")||!r.enumv(o,"measure","draft",measures,x.measure)||!r.number(o,"target","draft",true))return false;return true;});}
template<> Decoded<PrayerMark> decode<PrayerMark>(const QJsonValue&v){return run<PrayerMark>(v,[](Reader&r,const QJsonValue&v,PrayerMark&x){return prayerMark(r,v,"prayer_mark",x);});}
template<> Decoded<Config> decode<Config>(const QJsonValue&v){return run<Config>(v,[](Reader&r,const QJsonValue&v,Config&x){QJsonObject o;if(!r.object(v,"config",o))return false;x.json=o;if(!r.str(o,"location","config",x.location)||!r.str(o,"method","config",x.method)||!r.str(o,"sleep_time","config",x.sleepTime)||!r.str(o,"asr","config",x.location)||!r.boolean(o,"auto_location","config")||!r.number(o,"latitude","config")||!r.number(o,"longitude","config")||!r.number(o,"timezone_offset","config")||!r.nullableString(o,"last_location_provider","config")||!r.nullableString(o,"last_location_sync","config"))return false;return true;});}
template<> Decoded<Undo> decode<Undo>(const QJsonValue&v){return run<Undo>(v,[](Reader&r,const QJsonValue&v,Undo&x){QJsonObject o;if(!r.object(v,"undo",o)||!r.number(o,"undone","undo"))return false;x={o,o.value("undone").toInt()};return true;});}
template<> Decoded<MutationResult> decode<MutationResult>(const QJsonValue&v){return run<MutationResult>(v,[](Reader&r,const QJsonValue&v,MutationResult&x){return mutationResult(r,v,x);});}
template<> Decoded<Today> decode<Today>(const QJsonValue&v){return run<Today>(v,[](Reader&r,const QJsonValue&v,Today&x){QJsonObject o,b;if(!r.object(v,"today",o))return false;x.json=o;if(!r.str(o,"day","today",x.day)||!r.enumv(o,"block","today",blocks,x.block)||!r.number(o,"open","today")||!r.object(o.value("planning_block"),"today.planning_block",b))return false;QString z;if(!r.str(b,"day","today.planning_block",z)||!r.enumv(b,"start","today.planning_block",blocks,z))return false;for(auto k:{"items","current","upcoming"}){QJsonArray a;if(!r.array(o,k,"today",a))return false;auto &dest=QString(k)=="items"?x.items:(QString(k)=="current"?x.current:x.upcoming);for(int i=0;i<a.size();++i){DayItem d;if(!dayItem(r,a[i],"today."+QString(k)+QString("[%1]").arg(i),d))return false;dest.push_back(std::move(d));}}QJsonArray marks;if(!r.array(o,"prayer_marks","today",marks))return false;for(int i=0;i<marks.size();++i)if(!marks[i].isString()||!prayers.contains(marks[i].toString()))return r.fail(QString("today.prayer_marks[%1]").arg(i),"expected one of "+prayers.join('|'));if(!o.contains("timer"))return r.fail("today.timer","missing required field");if(!o.value("timer").isNull()){QJsonObject t;if(!r.object(o.value("timer"),"today.timer",t)||!r.str(t,"item_id","today.timer",z)||!r.str(t,"title","today.timer",z)||!r.str(t,"started_at","today.timer",z)||!r.number(t,"minutes","today.timer"))return false;}return true;});}

AnyDecoded decodeDayPlan(const QJsonValue&v){return any(decode<DayPlan>(v));} AnyDecoded decodeToday(const QJsonValue&v){return any(decode<Today>(v));}
AnyDecoded decodeStats(const QJsonValue&v){return any(decode<Stats>(v));} AnyDecoded decodeItem(const QJsonValue&v){return any(decode<Item>(v));}
